using System;using System.Collections.Generic;using System.Linq;using System.Reflection;using System.Threading.Tasks;using Newtonsoft.Json.Linq;
namespace KingmakerMountedCombat.Diagnostics {
internal static class Time{internal static int frameCount=1;}
internal sealed class Area{internal string AssetGuidThreadSafe="area";}
internal sealed class Player{internal string GameId="campaign";}
internal sealed class Game{internal static Game Instance;internal Player Player=new Player();internal SaveManager SaveManager=new SaveManager();internal Area CurrentlyLoadedArea=new Area();}
internal sealed class SaveInfo{internal enum SaveType{Manual,Auto}internal enum StateType{None,Serialization};internal string FileName,Name,GameId,GameName="Native",FolderName;internal Area Area;internal SaveType Type;internal StateType OperationState;internal bool IsActuallySaved,HasFileOnDisk;}
internal sealed class SaveManager{internal System.Collections.Generic.IEnumerator<object> SaveRoutine(SaveInfo saveInfo,bool forceAuto){yield break;}internal void PrepareSave(SaveInfo save){} }
internal sealed class NativeRoutine:IEnumerator<object>{internal Task Worker;public object Current=>null;object System.Collections.IEnumerator.Current=>Current;public bool MoveNext()=>false;public void Reset(){}public void Dispose(){}}
internal static class NativeSaveWorkerBoundary{internal static bool Matches=true;internal static bool TryReadWorker(IEnumerator<object> r,out Task worker){worker=Matches?(r as NativeRoutine)?.Worker:Task.FromResult(2);return worker!=null;}}
internal sealed class MountedPersistenceService{
 private sealed class SaveScope{public SaveInfo Requested,Prepared;public Task Worker;public IEnumerator<object> Routine;public Player World;public bool Completed;}
 private void RecordCompletedSave(SaveScope scope){}
 internal int SnapshotCount,CompletedSaveCount,StartRemoves,StagedRemoves;internal bool StartRemoveFails,StageRemoveFails;
 private Action starting,staged;
 internal event Action SaveSnapshotStarting{add{starting+=value;}remove{StartRemoves++;if(StartRemoveFails)throw new Exception("start release");starting-=value;}}
 internal event Action SaveSnapshotStaged{add{staged+=value;}remove{StagedRemoves++;if(StageRemoveFails)throw new Exception("stage release");staged-=value;}}
 internal void Header()=>starting?.Invoke();internal void Snapshot(){SnapshotCount++;staged?.Invoke();}
 internal object Scope(SaveInfo requested,SaveInfo prepared,Player player,Task worker=null,Task iteratorWorker=null,bool completed=true){worker=worker??Task.FromResult(1);return new SaveScope{Requested=requested,Prepared=prepared,Worker=worker,Routine=new NativeRoutine{Worker=iteratorWorker??worker},World=player,Completed=completed};}
}
internal static class Chunk7ManualSeedSelection{internal const string OutputName="KMC_C7_NATIVE_SEED";}
// Unrelated selection constants are compile-only boundaries for the actual save probe.
internal static class Chunk7ProgressionSelection{internal const string ManualOutputName="KMC_C7_PROGRESSION";internal static string ManualLeaf(int number)=>"Manual_"+number+"_"+ManualOutputName+".zks";}
internal static class Chunk7SmallFixtureSelection{internal const string SeedIdentity="KMC_C7_NO_MODS_OWNER_SEED";internal const string SeedHash="3405d7c813668ad646788efd746a62c1b16e1438fad1bc4bcbebc961821b924f";internal const string MainActorId="73681ef2-b281-4bc6-bc05-2de68c1616cb";}
internal static class MetadataBoundary{internal static bool Valid=true;internal static bool Matches()=>Valid;}
internal static class Priority{internal const int First=1,Last=0;}
internal sealed class HarmonyMethod{internal int prioritiy;internal HarmonyMethod(MethodInfo m){} }
internal sealed class HarmonyInstance{internal static int PatchCalls,UnpatchCalls,FailPatchAt;internal static bool FailUnpatch;internal static HarmonyInstance Create(string id)=>new HarmonyInstance();internal void Patch(MethodInfo method,HarmonyMethod before,HarmonyMethod after){PatchCalls++;if(PatchCalls==FailPatchAt)throw new Exception("partial patch");}internal void UnpatchAll(string id){UnpatchCalls++;if(FailUnpatch)throw new Exception("retained patch");}}
internal sealed class Labels{private readonly Dictionary<object,int> values=new Dictionary<object,int>();internal int Get(object value){if(value==null)return 0;if(!values.TryGetValue(value,out var id)){id=values.Count+1;values.Add(value,id);}return id;}}
internal static class ManualSaveProbeTests{
 static int pass,fail;static void Check(bool v,string m){if(!v)throw new Exception(m);}static void Good(string n,Action a){try{Time.frameCount=1;MetadataBoundary.Valid=true;NativeSaveWorkerBoundary.Matches=true;HarmonyInstance.PatchCalls=HarmonyInstance.UnpatchCalls=HarmonyInstance.FailPatchAt=0;HarmonyInstance.FailUnpatch=false;a();pass++;Console.WriteLine("PASS "+n);}catch(Exception e){fail++;Console.WriteLine("FAIL "+n+": "+e.Message);ResetActive();}}
 static void ResetActive(){typeof(Chunk7ManualSeedSaveProbe).GetField("active",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,null);}
 static void Throws(Action a){bool refused=false;try{a();}catch{refused=true;}Check(refused,"expected refusal");}
 sealed class F:IDisposable{internal Game G=new Game();internal MountedPersistenceService P=new MountedPersistenceService();internal Labels L=new Labels();internal SaveInfo Requested,Prepared;internal Chunk7ManualSeedSaveProbe Probe;internal bool WrongWorld;
 internal F(string leaf="Manual_1_KMC_C7_NATIVE_SEED.zks",string name="KMC_C7_NATIVE_SEED"){Game.Instance=G;Requested=new SaveInfo{Name=name,Area=G.CurrentlyLoadedArea};Prepared=new SaveInfo{Name=Requested.Name,Area=G.CurrentlyLoadedArea,GameId=G.Player.GameId,FileName=leaf,FolderName=@"C:\Virtual\"+leaf,HasFileOnDisk=true,IsActuallySaved=true};Probe=name=="KMC_C7_NATIVE_SEED"?new Chunk7ManualSeedSaveProbe(G,P,L.Get,()=>{if(WrongWorld)throw new InvalidOperationException("world");},Prepared.FileName):new Chunk7ManualSeedSaveProbe(G,P,L.Get,()=>{if(WrongWorld)throw new InvalidOperationException("world");},Prepared.FileName,name);}
 internal void Begin(){Probe.Install();Probe.Expect(Requested);Hook("SaveBefore",G.SaveManager,Requested,false);Hook("PreparedAfter",G.SaveManager,Prepared);P.Header();P.Snapshot();}
 internal void Finish(object scope=null){Hook("CompletedBefore",P,scope??P.Scope(Requested,Prepared,G.Player));P.CompletedSaveCount++;Probe.ObserveCallback();}
 public void Dispose(){Probe.Dispose();}}
 static void Hook(string name,params object[] args){var h=typeof(Chunk7ManualSeedSaveProbe).GetNestedType("Hooks",BindingFlags.NonPublic);h.GetMethod(name,BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,args);}
 static int Main(){
 Good("constructor captures only and Complete remains false",()=>{using(var f=new F()){Check(HarmonyInstance.PatchCalls==0&&!f.Probe.Complete,"constructor installed or completed");}});
 Good("exact requested prepared iterator worker and callback",()=>{using(var f=new F()){f.Begin();f.Finish();Check(f.Probe.Complete,"exact native sequence refused");var c=f.Probe.Capture();Check(((JArray)c["events"]).Count==6,"events missing");Check((int)c["events"][4]["worker"]!=(int)c["events"][4]["iterator"],"worker identity aliased");Check(ReferenceEquals(f.Probe.Written,f.Prepared),"prepared descriptor lost");}});
 Good("owner-seed field Manual 304 keeps the exact native worker and callback",()=>{using(var f=new F(Chunk7ManualDerivedSelection.OwnerSeedOutputLeaf,Chunk7ManualDerivedSelection.ManualOutputName)){f.Begin();f.Finish();Check(f.Probe.Complete,"owner-seed Manual 304 refused");}});
 Good("owner-seed field Manual 305 is outside the closed observer slot",()=>{Throws(()=>new F("Manual_305_KMC_C7_MANUAL_DERIVED_FIELD.zks",Chunk7ManualDerivedSelection.ManualOutputName));});
 foreach(var mode in new[]{"requested","prepared","world","incomplete","different worker","faulted","canceled","saving state","missing output"}){var name=mode;Good("completed scope refuses "+name,()=>{using(var f=new F()){f.Begin();var requested=name=="requested"?new SaveInfo():f.Requested;var prepared=name=="prepared"?new SaveInfo():f.Prepared;var world=name=="world"?new Player():f.G.Player;Task worker=null,other=null;if(name=="different worker")other=Task.FromResult(2);if(name=="faulted")worker=Task.FromException(new Exception("fault"));if(name=="canceled"){var t=new TaskCompletionSource<int>();t.SetCanceled();worker=t.Task;}if(name=="saving state")f.Prepared.OperationState=SaveInfo.StateType.Serialization;if(name=="missing output")f.Prepared.HasFileOnDisk=false;f.Finish(f.P.Scope(requested,prepared,world,worker,other,name!="incomplete"));Check(!f.Probe.Complete&&((JArray)f.Probe.Capture()["errors"]).Count>0,"foreign or unfinished scope completed");}});}
 foreach(var mode in new[]{"manager","descriptor","force auto","duplicate request","foreign prepared manager","foreign prepared leaf","early callback","duplicate callback","world changed"}){var name=mode;Good("native save observation refuses "+name,()=>{using(var f=new F()){if(name=="manager"||name=="descriptor"||name=="force auto"){f.Probe.Install();f.Probe.Expect(f.Requested);Hook("SaveBefore",name=="manager"?new SaveManager():f.G.SaveManager,name=="descriptor"?new SaveInfo():f.Requested,name=="force auto");}else{f.Begin();if(name=="duplicate request")Hook("SaveBefore",f.G.SaveManager,f.Requested,false);if(name=="foreign prepared manager")Hook("PreparedAfter",new SaveManager(),f.Prepared);if(name=="foreign prepared leaf"){f.Prepared.FileName="Manual_2_other.zks";Hook("PreparedAfter",f.G.SaveManager,f.Prepared);}if(name=="early callback")f.Probe.ObserveCallback();if(name=="world changed")f.WrongWorld=true;f.Finish();if(name=="duplicate callback")f.Probe.ObserveCallback();}Check(!f.Probe.Complete,"foreign native callback accepted");}});}
 Good("partial install remains caller owned and retry release",()=>{var f=new F();HarmonyInstance.FailPatchAt=2;Throws(()=>f.Probe.Install());Check(!f.Probe.Complete&&HarmonyInstance.PatchCalls==2,"partial install complete");HarmonyInstance.FailUnpatch=true;Throws(()=>f.Dispose());Check(HarmonyInstance.UnpatchCalls==1,"release not attempted");HarmonyInstance.FailUnpatch=false;f.Dispose();Check(HarmonyInstance.UnpatchCalls==2,"retry not attempted");Throws(()=>f.Probe.Install());});
 Good("each observer lease release attempted independently",()=>{var f=new F();f.Probe.Install();f.P.StartRemoveFails=true;f.P.StageRemoveFails=true;HarmonyInstance.FailUnpatch=true;Throws(()=>f.Dispose());Check(f.P.StartRemoves==1&&f.P.StagedRemoves==1&&HarmonyInstance.UnpatchCalls==1,"independent release skipped");f.P.StartRemoveFails=f.P.StageRemoveFails=false;HarmonyInstance.FailUnpatch=false;f.Dispose();Check(f.P.StartRemoves==2&&f.P.StagedRemoves==2&&HarmonyInstance.UnpatchCalls==2,"leases not retried");});
 Console.WriteLine("TOTAL PASS="+pass+" FAIL="+fail);return fail==0?0:1;
 }
}
}
